INSERT INTO T_USER_ACTION_LOG (
    LOG_SEQ, ACTION_DT, ACTION_TM, USER_ID, LOGIN_IP, SCREEN_KEY, SCREEN_NAME, ACTION,
    REQ_METHOD, REQ_URI, HANDLER, ACTION_PARAM, REASON, RESULT_YN, RESULT_MSG, ELAPSED_MS
) VALUES (
    SEQ_T_USER_ACTION_LOG.NEXTVAL, #{actionDate}, #{actionTime}, #{userId}, #{loginIp,jdbcType=VARCHAR},
    #{screenKey,jdbcType=VARCHAR}, #{screenName,jdbcType=VARCHAR}, #{action},
    #{reqMethod}, #{reqUri}, #{handler,jdbcType=VARCHAR}, SUBSTRB(#{actionParam,jdbcType=VARCHAR}, 1, 4000),
    SUBSTRB(#{reason,jdbcType=VARCHAR}, 1, 500), #{resultYn}, SUBSTRB(#{resultMsg,jdbcType=VARCHAR}, 1, 500), #{elapsedMs,jdbcType=NUMERIC}
)
